<?php echo form_open(get_uri('warehouses/save'),['id'=>'warehouse-form']);echo csrf_field(); ?><div class="modal-header"><h5 class="modal-title"><?php echo empty($row->id)?'Nuevo almacén':'Editar almacén'; ?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="id" value="<?php echo(int)($row->id??0); ?>"><label>Nombre</label><input class="form-control" name="name" required value="<?php echo esc($row->name??''); ?>"><label>Código</label><input class="form-control text-uppercase" name="code" required value="<?php echo esc($row->code??''); ?>"><label>Dirección</label><textarea class="form-control" name="address"><?php echo esc($row->address??''); ?></textarea><div class="row"><div class="col-md-6"><label>Responsable</label><input class="form-control" name="responsible_name" value="<?php echo esc($row->responsible_name??''); ?>"></div><div class="col-md-6"><label>Teléfono</label><input class="form-control" name="phone" value="<?php echo esc($row->phone??''); ?>"></div></div><label>Notas</label><textarea class="form-control" name="notes"><?php echo esc($row->notes??''); ?></textarea><label>Estado</label><?php echo form_dropdown('status',['active'=>'Activo','inactive'=>'Inactivo'],$row->status??'active',"class='form-control'"); ?></div><div class="modal-footer"><button class="btn btn-default" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div><?php echo form_close(); ?><script>$('#warehouse-form').appForm({onSuccess:function(){location.reload();}});</script>
